def decode(mixed_qkv: torch.Tensor, a: torch.Tensor, b: torch.Tensor, A_log: torch.Tensor, dt_bias: torch.Tensor, base: torch.Tensor, out: torch.Tensor, indices: torch.Tensor, scratch: DeferredScratch, scale: float=K ** (-0.5)):
    p, w = validate(base, scratch)
    _check_indices(indices, base)
    m = int(mixed_qkv.shape[0])
    rows = (1, 2, 4, 8, 16, 24, 32, 48, 64, 96, 128, 160) if base.dtype == torch.bfloat16 else (32, 48, 64, 96, 128, 160)
    if m not in rows or tuple(mixed_qkv.shape) != (m, QKV):
        raise ValueError(f'only packed rows {rows} QKV6144')
    if mixed_qkv.dtype != torch.bfloat16 or not mixed_qkv.is_cuda or mixed_qkv.device != base.device or (mixed_qkv.stride(1) != 1):
        raise ValueError('mixed_qkv must be CUDA BF16 [M,6144] stride1')
    if tuple(a.shape) != (m, HV) or tuple(b.shape) != (m, HV) or a.dtype != torch.bfloat16 or (b.dtype != torch.bfloat16) or (a.device != base.device) or (b.device != base.device) or (a.stride(1) != 1) or (b.stride(1) != 1):
        raise ValueError('a/b must be CUDA BF16 [M,16] stride1')
    if tuple(A_log.shape) != (HV,) or A_log.dtype != torch.float32 or tuple(dt_bias.shape) != (HV,) or (dt_bias.dtype != torch.bfloat16) or (A_log.device != base.device) or (dt_bias.device != base.device) or (A_log.stride(0) != 1) or (dt_bias.stride(0) != 1):
        raise ValueError('A_log FP32 and dt_bias BF16 need 16 contiguous heads')
    if tuple(out.shape) != (m, 1, HV, V) or out.dtype != torch.bfloat16 or out.device != base.device or (not out.is_contiguous()) or (tuple(indices.shape) != (m,)):
        raise ValueError('out contiguous BF16 [M,1,16,128], indices [M]')
    if not math_isfinite_positive(scale):
        raise ValueError('scale must be finite and positive')
    if base.dtype == torch.bfloat16 and exp is tl.exp:
        from ...gdn.bf16_small_gluon import decode as bf16_decode, supports_shape
        if supports_shape(m, HV):
            bf16_decode(mixed_qkv, a, b, A_log, dt_bias, base, out, indices, scratch, scale)
            return out
    global _LAST_KERNEL
    _LAST_KERNEL = _ordered_decode[NV, HV, m](mixed_qkv, a, b, A_log, dt_bias, out, base, indices, scratch.pending_k, scratch.pending_d, scratch.coeff, scratch.prefix, scratch.age, mixed_qkv.stride(0), a.stride(0), b.stride(0), base.stride(0), indices.stride(0), p, w, scale, H, HV, V, K, BV, NV, num_warps=1, num_stages=3)
    return out
